pm.test("Несуществующий пользователь возвращает 404", function () {
    pm.response.to.have.status(404);
});

pm.test("Ответ содержит пустой JSON-объект", function () {
    const body = pm.response.json();
    pm.expect(body).to.deep.equal({});
});

pm.test("Пользователь найден", function () {
    pm.response.to.have.status(200);
});

pm.test("ID пользователя равен 1", function () {
    const user = pm.response.json();
    pm.expect(user.id).to.equal(1);
});

pm.test("Name пользователя равен Leanne Graham", function () {
    const user = pm.response.json();
    pm.expect(user.name).to.equal("Leanne Graham");
});

pm.test("e-mail пользователя не пустая строка", function () {
    const user = pm.response.json();
    pm.expect(typeof user.email).to.equal("string");
    pm.expect(user.email.trim()).to.not.equal("");
});
